WFJ.Data.add("gossip", {
  ["dc025e97e72ee88c"] = { "Per ora reggono. Alziamo la temperatura...", "." },
  ["dc10f5e84728daaa"] = { "Ho smarrito la via nel Sogno. Percepisco la sua forza vitale, ma i miei poteri non sono ancora abbastanza forti da stabilire un contatto.", "." },
  ["dc11fd2f5e220f14"] = { "Ricordati le mie parole, imp: ti prenderò. E quando succederà!", "." },
  ["dc149fe8bb7e5ac4"] = { "Salute, {class}. Brutti tempi sono questi, amico mio, perché la nostra città è sotto assedio! Gli orchi ⟦Blackrock=Roccianera⟧ attaccano dal ⟦Stonewatch Keep=Mastio di Guardamasso⟧, i Mantombroso incombono sulla ⟦Tower of Ilgalar=Torre di Ilgalar⟧ e il branco di gnoll di ⟦Redridge=Crestarossa⟧ si fa sempre più forte. Spero che tu non sia qui in vacanza...", "." },
  ["dc196b735d38840f"] = { "Il popolo delle ⟦Westfall=Marche Occidentali⟧ rende omaggio a {name}, che ha difeso la libertà con coraggio e valore.", "." },
  ["dc237f7478039df3"] = { "Un compito mi preme, ma non ho il tempo di occuparmene di persona. Posso affidartelo?", "." },
  ["dc2391107ed4da08"] = { "Monty è il mio nome e i ratti son la mia specialità.", "." },
  ["dc313d6675d09e37"] = { "Oh, {name}, aspetta un attimo! C'è un'altra cosa! Torna qui!", "." },
  ["dc32d9b88c1648c2"] = { "Vai ora, {name}. Trova Volcor... e ricorda, la magia che ti protegge svanirà se interagisci con qualcuno in modo diverso dal parlare.", "." },
  ["dc3534f18ee24c13"] = { "Che la Luce sia con te, {name}.", "." },
  ["dc35bcd47ead4303"] = { "Lo scudo è caduto! Insorgete, Atal'ai! Insorgete!", "." },
  ["dc3dbe84d2023471"] = { "Non abbiamo tempo da perdere. È una corsa davvero lunga! Coprimi!", "." },
  ["dc3e04b8a4a6bbf5"] = { "La capitana Balinda Cordipietra è morta! Sconfiggete Vanndar e la battaglia sarà nostra!", "." },
  ["dc4c8e91b12de3ac"] = { "Vai a prenderlo!!", "." },
  ["dc4e4d41b8cd9c9f"] = { "D'accordo, ti insegnerò, ma voglio che tu faccia una cosa per me. È importante, quindi ascolta bene.", "." },
  ["dc532d7574c75523"] = { "Ti dico una cosa. Visto che ti credi un tipo da eroe, se riesci ad attraversare le ⟦Badlands=Maleterre⟧ fino alla ⟦Searing Gorge=Gorgia Rovente⟧ e a riportarmi qualcosa che dimostri il tuo eroismo, vedrò cosa posso fare per procurarti una chiave.\n\nNell'angolo più a sud-est della ⟦Searing Gorge=Gorgia Rovente⟧ c'è una signora tosta quasi quanto me, ⟦Margol the Rager=Margol il Rabbioso⟧. Forse dovresti indagare.", "." },
  ["dc582949c8455fe8"] = { "Riposa un po' le tue stanche ossa.", "." },
  ["dc6064c4475a4e4c"] = { "Cerca di renderti utile, {race}. TIRAMI FUORI DI QUI! Il sommo inquisitore ha la chiave.", "." },
  ["dc609f4a9e0c8389"] = { "Laurena è la somma sacerdotessa di ⟦Stormwind=Roccavento⟧. La trovi nella Cattedrale della Luce, in Cathedral Square.", "." },
  ["dc64cff481232ee0"] = { "Mi hai disturbato per questo? Faresti meglio a legarti un coniglio morto sulla schiena e a correre attraverso una tana di troll che indossare quel ciarpame.", "." },
  ["dc65ba7dff21703a"] = { "Ben <trovato/trovata>, {name}. È bello vedere che druidi come te prendono parte attiva alla protezione dei boschetti.", "." },
  ["dc688d6afbacd0f0"] = { "Ti presento il ⟦Libram of Resilience=Compendio sulla Resilienza⟧.", "." },
  ["dc6ec8139ae1e445"] = { "Non costringetemi ad agire, ragazzini! Userò le vostre pelli per foderarmi gli stivali.", "." },
  ["dc6f78ab4f426685"] = { "Voglio le loro teste, {name}, non scuse.", "." },
  ["dc75077e9ec884f3"] = { "Guidi gli spiriti nell'acciaio a proteggere e difendere con un'abilità molto superiore alla mia. L'allievo ha superato il maestro, e ora devo mandarti dove la tua istruzione potrà continuare. {name}, devi cercare ⟦Shayis Steelfury=Shayis Furiaferro⟧ a Orgrimmar. È la miglior Fabbro d'Armature che abbia mai conosciuto, e può insegnarti molto.", "." },
  ["dc758d1e7f91b06c"] = { "Allora, per come la vedo io, {name}, abbiamo due possibilità per uscire da questa caverna.\n\nPossiamo uscire di soppiatto: io uso il mantello che mi hai dato e tu dovrai cavartela per conto tuo; oppure, e questa potrebbe essere la scelta più difficile viste le mie ferite, ci apriamo la strada combattendo spalla a spalla.\n\nLascio decidere a te, visto che conosci i tuoi punti di forza meglio di me.", "." },
  ["dc8ca5f2e9a5c28a"] = { "Ho scoperto questa grotta il nostro primo giorno qui. Credo che l'energia della pietra possa tornarci utile.", "." },
  ["dc962b7ad4e00ac7"] = { "Ja mon, io raccogliere pesciolini per l'⟦Horde=Orda⟧. Loro prepararsi per grande guerra nel deserto ad ⟦Ahn'Qiraj=Ahn'qiraj⟧, e chiedere a me di portare $2103w di Pinnagialla Maculato. Ma adesso noi avere solo $2102w. Tu qui per aiutare?", "." },
  ["dc963b65c27d0058"] = { "Ho sentito dire che Deneb Walker, rintanato a Stromgarde, ha un libro che di certo ti aiuterà a migliorare le tue tecniche di ⟦First Aid=Primo Soccorso⟧.", "." },
  ["dca9eef11716207e"] = { "Una lama nascosta nella manica può fare la differenza tra te steso morto in un vicolo e il tuo avversario a faccia in giù nel suo stesso sangue.", "." },
  ["dcad1c38f201ac49"] = { "Dov'è l'anziano Venargento?", "." },
  ["dcb39d23cc7e40fd"] = { "Racconta pure la tua storia, Baristolth.", "." },
  ["dcb5d1b745fdc80b"] = { "Truppe fresche affluiscono al ⟦Iceblood Garrison=Presidio di Brinarossa⟧! Il capitano Galvangar arriverà presto, e presto comincerà una nuova battaglia!", "." },
  ["dcb9a09d97ab3529"] = { "Un attimo che lo ricucio...", "." },
  ["dcc2996616f0ef95"] = { "I miei insegnamenti sarebbero troppo avanzati per te, a questo punto. Se vuoi saperne di più sulle pozioni, parla piuttosto con ⟦Tel'Athir=Tel'athir⟧, qui.", "." },
  ["dcc4abaa5cd132fa"] = { "Ah, tornare giovani e scoprire le pozioni per la prima volta. Grazie per avermi rinfrescato la memoria, {name}. Ora va' a condividere quell'entusiasmo giovanile con ⟦Milla Fairancora=Milla Ferancora⟧, laggiù.", "." },
  ["dcc4fa216996ef14"] = { "Alzati, piccolo dragone rosso... e distruggili!", "." },
  ["dcc5a8048102a5f3"] = { "Ogni cosa ha uno spirito: se impari ad ascoltarlo, puoi fargli prendere qualunque forma tu voglia. La Forgiatura non significa battere il metallo, costringerlo a piegarsi al tuo volere. Significa ascoltare lo spirito dentro l'acciaio e guidarlo verso la forma che sai che vuole prendere.", "." },
  ["dcc921bcd22ff94c"] = { "Figli della Notte, rispondete al richiamo della vostra regina!", "." },
  ["dccd75e599b5cfe6"] = { "%s sfoglia i libri.", "." },
  ["dce4f6adc901c41e"] = { "Non senti l'angoscia della Madre Terra per i suoi figli perduti, i non morti? Parla in fretta, {name}. Ogni secondo mi costa caro. Dobbiamo aiutarli a ritrovare la strada verso di lei!", "." },
  ["dce7a64fa924a17f"] = { "Dicci solo quello che sai sulla ⟦Shady Rest Inn=Locanda Ombracalma⟧, e non ti spacco il cranio.", "." },
  ["dce998342d526447"] = { "Resta anche dopo la fine dello spettacolo pirotecnico. Trova un calice e alzalo per brindare ai tuoi valorosi amici!", "." },
  ["dceb5dacd7127dc0"] = { "Forse questo non era il posto migliore per una bottega, dopotutto...", "." },
  ["dcf0504f0f8eb1cb"] = { "Onori gli spiriti degli animali che devi uccidere non lasciando che vadano sprecati. ⟦Aska Mistrunner=Aska Cavalca Nebbia⟧ ti mostrerà come fare. Ha una cucina sull'altura.", "." },
  ["dcf65d9d24183972"] = { "Cos'è l'E'ko?", "." },
})
